Please enable Javascript to view this website

#main-article {
top: unset !important;
padding-bottom: unset !important;
min-block-size: 100dvh;
}
@media (min-width: 768px) {
#main-article {
min-block-size: 100vh;
}
}

(async () => {
const articleContainer = document.querySelector("#main-article");
const preview = window.location.origin.includes("preview")

const stylesUrl = preview
? "https://creative-dev.espnqa.com/26_vs_wnba-30th-anniversary/assets/index.css?v=09170210"
: "https://creative-dev.espn.com/26_vs_wnba-30th-anniversary/assets/index.css?v=09170210";
const link = document.createElement("link");
link.setAttribute("rel", "stylesheet");
link.setAttribute("href", stylesUrl);
articleContainer.insertAdjacentElement("afterbegin", link)

const scriptUrl = preview
? "https://creative-dev.espnqa.com/26_vs_wnba-30th-anniversary/assets/index.js?v=09170210"
: "https://creative-dev.espn.com/26_vs_wnba-30th-anniversary/assets/index.js?v=09170210";
await import(scriptUrl);
})();
